import { a as array_to_key_object } from "../../../../chunks/helper.js";
import { g as get_changers } from "../../../../chunks/changer.service.js";
import { g as get_currencies } from "../../../../chunks/currency.service.js";
import { error } from "@sveltejs/kit";
import { a as Countries } from "../../../../chunks/countries.js";
import { C as CountriesToCurrencies } from "../../../../chunks/countries-to-currencies.js";
const USD = "US";
const EUR = ["DE", "AD", "AT", "BE", "CY", "EE", "FI", "FR", "GR", "IE", "IT", "LV", "LT", "LU", "MT", "MC", "NL", "PT", "SM", "SK", "SI", "ES", "VA"];
const GBP = "GB";
const NGN = "NG";
const CountryCodeByCurrency = {
  USD,
  EUR,
  GBP,
  NGN
};
const load = async ({ fetch, params, url }) => {
  async function getPairChangers(pair_code, changer_service) {
    try {
      const response = await fetch(
        `/api/pairs/changers?pair_code=${pair_code}&changer_service=${changer_service}`
      );
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      return await response.json();
    } catch (error2) {
      console.error("Error fetching pair changers:", error2);
      return [];
    }
  }
  try {
    let urlParams = url.searchParams;
    const convert = {
      From: urlParams.get("From") || "usd",
      To: urlParams.get("To") || "ngn",
      Amount: urlParams.get("Amount") || 1
    };
    let remittanceRates = await getPairChangers(`${convert.From}${convert.To}`, "remittance");
    let rampRates = await getPairChangers(`${convert.From}${convert.To}`, "ramp");
    let cardRates = await getPairChangers(`${convert.From}${convert.To}`, "card");
    const changers = await get_changers();
    const currencies = await get_currencies();
    const countries = Countries;
    const countriesToCurrencies = CountriesToCurrencies;
    const countryCodeByCurrency = CountryCodeByCurrency;
    if (currencies.length == 0) {
      throw error(500, "Currencies data failed.");
    }
    return {
      changers: array_to_key_object(changers, "code"),
      currencies,
      convert,
      countries,
      countriesToCurrencies,
      countryCodeByCurrency,
      remittanceRates,
      rampRates,
      cardRates
    };
  } catch (e) {
    console.log(e);
    throw error(502, `Unable to fetch an important data`);
  }
};
export {
  load
};
