import { p as parseJSONSafe } from "./functions.js";
const get_all_alerts = async (fetch_event) => {
  const endpoint = "/api/price_alert/get_all";
  let res;
  if (fetch_event) {
    res = await fetch_event(endpoint, {
      method: "GET"
    });
  } else {
    res = await fetch(endpoint, {
      method: "GET"
    });
  }
  const result = await res.json();
  return parseJSONSafe(result);
};
