import { g as get_changers } from "../../../chunks/changer.service.js";
import { g as get_currencies } from "../../../chunks/currency.service.js";
const load = async ({ url }) => {
  const providers = await get_changers();
  const currencies = await get_currencies();
  const create_pairs = Object.entries(currencies).map(([_, value]) => {
    if (value.code !== "ngn") {
      return {
        label: value.code.toUpperCase() + " - NGN",
        value: value.code + "ngn",
        description: `The price of ${value.name} in Naira`,
        quote: "ngn",
        base: value.code
      };
    }
    return null;
  }).filter((pair) => pair !== null);
  let pair_list = create_pairs;
  let slug = url.pathname.split("/")[3];
  return {
    currencies,
    providers,
    pair_list,
    slug
  };
};
export {
  load
};
