async function PUT({ request, fetch }) {
  const { email, interval } = await request.json();
  const payload = {
    email,
    interval
  };
  const endpoint = getEndpointV1("/alerting");
  const res = await fetch(endpoint, basicAuth("PUT", payload, "system"));
  const result = await res.json();
  return json(result);
}
