import { b as basicAuth } from "../../../chunks/helper.js";
import { b as bearer } from "../../../chunks/functions.js";
import { g as getEndpointV1 } from "../../../chunks/utilities.js";
const load = async ({ url, cookies }) => {
  const params = url.searchParams;
  const auth_token = params.get("auth") || cookies.get("auth") || "";
  const confirm_token = params.get("confirm") || "";
  let auth = null;
  let confirm = null;
  let alerts;
  const savedToken = cookies.get("auth") || "";
  if (savedToken.length > 0) {
    console.log(savedToken);
    auth = { status: "success" };
    alerts = await getAlerts(savedToken);
  } else if (auth_token != "") {
    const result = await getAuth(auth_token);
    console.log(result);
    auth = result;
    if (result.status == "success") {
      cookies.set("auth", result.data.token, {
        path: "/",
        maxAge: 60 * 60
      });
      alerts = await getAlerts(result.data.token);
    }
  }
  if (confirm_token != "") {
    const result = await confirmAlert(confirm_token);
    console.log(result);
    confirm = result;
  }
  return {
    confirm,
    auth,
    alerts
  };
};
async function getAlerts(token) {
  const endpoint = getEndpointV1("/auth/alerting");
  const res = await fetch(endpoint, bearer("GET", token, {}));
  const result = await res.json();
  if (result.status == "error") {
    return [];
  }
  return result.data;
}
async function getAuth(token) {
  const payload = {
    token
  };
  const endpoint = getEndpointV1("/public/alerting/auth");
  const res = await fetch(endpoint, basicAuth("POST", payload, "system"));
  const result = await res.json();
  return result;
}
async function confirmAlert(token) {
  const payload = {
    token
  };
  const endpoint = getEndpointV1("/public/alerting/confirm");
  const res = await fetch(endpoint, basicAuth("POST", payload, "system"));
  const result = await res.json();
  return result;
}
export {
  load
};
