import { e as get_alert } from "../../../../../chunks/alert.service.js";
const load = async ({ fetch, url }) => {
  try {
    const alert_id = url.searchParams.get("edit_alert") || "";
    if (alert_id && alert_id !== "") {
      const alert = await get_alert(alert_id, fetch);
      return {
        alert: alert.data
      };
    }
  } catch (error) {
    console.log(error.message);
  }
  return {};
};
export {
  load
};
