import { error } from "@sveltejs/kit";
import { g as get_changers } from "../../../../chunks/changer.service.js";
import { c as currencySymbols } from "../../../../chunks/currency-symbols.js";
import { c as currencies } from "../../../../chunks/currencies.js";
const getHighlights = async (fetch, pair) => {
  try {
    const res = await fetch("/api/highlights?max=5&pair=" + pair);
    if (!res.ok) throw new Error(`Failed to fetch highlights: ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error("getHighlights error:", err);
    return [];
  }
};
const load = async ({ fetch, url, parent, cookies }) => {
  try {
    const { VALID_CURRENCIES } = await parent();
    const page = Number(url.searchParams.get("page") || "1");
    const rawCurrency = (url.searchParams.get("currency") ?? "USD").toUpperCase();
    const isValidCurrency = VALID_CURRENCIES.includes(rawCurrency);
    const currency = isValidCurrency ? rawCurrency : "USD";
    const pair = `${currency}NGN`.toLowerCase();
    let showHighlights = true;
    if (cookies.get("showHighlights")) {
      showHighlights = cookies.get("showHighlights") === "true";
    }
    const [rawProviders, highlights] = await Promise.all([
      get_changers(),
      getHighlights(fetch, pair)
    ]);
    if (!rawProviders || rawProviders.length === 0) {
      throw error(500, {
        message: "Unable to fetch platforms data, try again in a few minutes."
      });
    }
    const availablePairs = [];
    const providers = {};
    for (const provider of rawProviders) {
      if (provider.changer_tags && provider.changer_tags.includes("virtualcard")) {
        providers[provider.code] = provider;
        try {
          if (provider.pairs) {
            Object.keys(provider.pairs).forEach((pair2) => {
              if (!availablePairs.includes(pair2)) {
                availablePairs.push(pair2);
              }
            });
          }
        } catch (err) {
          console.error(err);
        }
      }
    }
    const mergedCurrencies = {
      ...currencies.coins,
      ...currencies.fiat
    };
    return {
      providers,
      page,
      currency,
      currencySymbols,
      isValidCurrency,
      mergedCurrencies,
      highlights,
      showHighlights
    };
  } catch (err) {
    console.error("Page load error:", err);
    throw error(500, {
      message: "Unable to display data, try again in a few minutes."
    });
  }
};
export {
  load
};
