import { error } from "@sveltejs/kit";
async function load() {
  try {
    const codesModule = await import("../../../../chunks/bank-ussd.js");
    const banksModule = await import("../../../../chunks/banks.js");
    const codes = codesModule.default;
    const banks = banksModule.default.ng;
    const mappedBanks = Object.entries(banks).map(
      ([bankKey, bank]) => {
        const bankCodes = codes[bankKey] || {};
        return {
          id: bankKey,
          name: bank.name,
          city: bank.city || "",
          address: bank.address || "",
          branch: bank.branch || "",
          ussd: {
            start: bankCodes?.start || "",
            airtime_self: bankCodes?.airtime?.[0] || "",
            transfer_to_same_bank: bankCodes?.transfer?.[0] || ""
          }
        };
      }
    );
    const banksData = mappedBanks.filter((bankData) => Object.keys(bankData.ussd).length > 0);
    return { banksData };
  } catch (e) {
    throw error(404, "Could not find or map USSD codes");
  }
}
export {
  load
};
